mapper.select:

WHERE pa.user_id = #{userId}
ORDER BY pa.create_time DESC, pa.id DESC
LIMIT 1





            AND pa.status = #{q.status}


            AND (u.user_name LIKE CONCAT('%', #{q.userName}, '%')
                 OR u.nick_name LIKE CONCAT('%', #{q.userName}, '%'))


            AND u.nick_name LIKE CONCAT('%', #{q.realName}, '%')



        AND pa.dept_id = #{deptId}


ORDER BY pa.create_time DESC, pa.id DESC

SELECT COUNT(1) FROM promotion_application pa

    pa.status = #{status}
    AND pa.dept_id = #{deptId}

SELECT u.user_id AS userId, u.user_name AS userName, u.nick_name AS nickName, u.dept_id AS deptId, d.dept_name AS deptName, u.position_id AS positionId, p.position_name AS positionName, p.position_code AS positionCode, u.user_status AS userStatus, CASE WHEN u.protocol_status = 1 THEN 1 ELSE 0 END AS protocolSigned, pa.id AS applicationId, pa.application_no AS applicationNo, pa.status AS applicationStatus, pa.reject_reason AS rejectReason, pa.supplement AS supplement, pa.cert_no AS certNo, pa.create_time AS submittedAt, pa.dept_approve_time AS decidedAt, au.nick_name AS deptApproveName FROM sys_user u JOIN sys_dept d ON d.dept_id = u.dept_id AND d.del_flag = '0' LEFT JOIN position p ON p.id = u.position_id AND p.deleted = 0 LEFT JOIN ( SELECT pa1.user_id, MAX(pa1.id) AS max_id FROM promotion_application pa1 GROUP BY pa1.user_id ) lax ON lax.user_id = u.user_id LEFT JOIN promotion_application pa ON pa.id = lax.max_id LEFT JOIN sys_user au ON au.user_id = pa.dept_approve_by WHERE u.del_flag = '0' AND u.status = '0' AND u.user_status IN ('PRE_TRAINEE', 'FORMAL_TRAINEE', 'PENDING_PROMOTE') AND EXISTS (SELECT 1 FROM sys_user_role ur JOIN sys_role r ON r.role_id = ur.role_id WHERE ur.user_id = u.user_id AND r.role_key IN ('PRE_TRAINEE', 'FORMAL_TRAINEE'))
AND u.dept_id = #{deptId}
ORDER BY u.dept_id ASC, u.user_id ASC
